import java.util.ArrayList;
import java.util.List;

/**
 * Splits a long text into lines no wider than a given limit,
 * breaking only at spaces. Words longer than the limit stay whole.
 */
public final class Wrapper {
    private Wrapper() {}

    public static List<String> wrap(String text, int limit) {
        if (limit < 1) {
            throw new IllegalArgumentException("limit must be positive");
        }
        List<String> lines = new ArrayList<>();
        StringBuilder current = new StringBuilder();
        for (String word : text.trim().split("\\s+")) {
            if (current.length() > 0 && current.length() + 1 + word.length() > limit) {
                lines.add(current.toString());
                current.setLength(0);
            }
            if (current.length() > 0) {
                current.append(' ');
            }
            current.append(word);
        }
        if (current.length() > 0) {
            lines.add(current.toString());
        }
        return lines;
    }
}

