# text_utils.py - small helpers for normalising text before indexing
import re
import unicodedata

_WS = re.compile(r"\s+")
_PUNCT = re.compile(r"[^\w\s-]")

def strip_accents(s: str) -> str:
    # NFKD splits letters from their combining marks, which we then drop.
    decomposed = unicodedata.normalize("NFKD", s)
    return "".join(c for c in decomposed if not unicodedata.combining(c))

def slugify(title: str, max_len: int = 60) -> str:
    s = strip_accents(title).lower()
    s = _PUNCT.sub("", s)
    s = _WS.sub("-", s.strip())
    return s[:max_len].rstrip("-")

def chunk(words: list[str], size: int):
    # Yield consecutive slices of at most `size` items.
    for i in range(0, len(words), size):
        yield words[i : i + size]

if __name__ == "__main__":
    print(slugify("Crème brûlée: a simple guide!"))

