#!/usr/bin/env python3
"""Merge sorted log shards into one stream by timestamp."""
import heapq
import sys
from pathlib import Path


def read_shard(path):
    # Each line starts with an ISO timestamp followed by a space.
    with open(path, encoding="utf-8") as fh:
        for line in fh:
            line = line.rstrip("\n")
            if not line:
                continue
            ts, _, rest = line.partition(" ")
            yield ts, rest


def merge(paths):
    streams = [read_shard(p) for p in paths]
    for ts, rest in heapq.merge(*streams, key=lambda item: item[0]):
        yield f"{ts} {rest}"


def main(argv):
    if len(argv) < 2:
        print("usage: merge_logs.py SHARD [SHARD ...]", file=sys.stderr)
        return 2
    paths = [Path(a) for a in argv[1:]]
    missing = [p for p in paths if not p.exists()]
    if missing:
        print("missing shards:", ", ".join(map(str, missing)), file=sys.stderr)
        return 1
    for line in merge(paths):
        print(line)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

