//! # ringbuf
//!
//! A fixed-capacity ring buffer of bytes that supports one writer and one
//! reader on the same thread. It is intended for small protocol parsers that
//! need to hold partial frames between reads.
//!
//! ## Quick start
//!
//! ```
//! use ringbuf::RingBuffer;
//!
//! let mut rb = RingBuffer::with_capacity(8);
//! rb.write(b"abc").unwrap();
//! rb.write(b"de").unwrap();
//!
//! let mut out = [0u8; 4];
//! let n = rb.read(&mut out);
//! assert_eq!(&out[..n], b"abcd");
//! assert_eq!(rb.len(), 1);
//! ```
//!
//! ## Behaviour
//!
//! * `write` is all or nothing. If the data does not fit, nothing is written
//!   and `Err(Full)` is returned with the number of free bytes.
//! * `read` copies as many bytes as the destination slice can hold and
//!   returns the count. It never blocks.
//! * `peek` copies without consuming, which is handy for checking a frame
//!   header before the whole frame has arrived.
//! * Capacity is fixed at construction time. There is no growth.

use std::fmt;

/// Error returned by [`RingBuffer::write`] when there is not enough room.
#[derive(Debug, PartialEq, Eq)]
pub struct Full {
    pub free: usize,
}

impl fmt::Display for Full {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "ring buffer full, {} bytes free", self.free)
    }
}

impl std::error::Error for Full {}

/// A fixed-size circular byte buffer.
pub struct RingBuffer {
    buf: Vec<u8>,
    head: usize, // index of the next byte to read
    len: usize,  // number of valid bytes
}

impl RingBuffer {
    /// Creates a buffer that can hold `capacity` bytes. Panics if zero.
    pub fn with_capacity(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be non-zero");
        RingBuffer { buf: vec![0; capacity], head: 0, len: 0 }
    }

    pub fn capacity(&self) -> usize {
        self.buf.len()
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn free(&self) -> usize {
        self.capacity() - self.len
    }

    /// Appends `data`, or returns [`Full`] without modifying the buffer.
    pub fn write(&mut self, data: &[u8]) -> Result<(), Full> {
        if data.len() > self.free() {
            return Err(Full { free: self.free() });
        }
        let cap = self.capacity();
        let mut tail = (self.head + self.len) % cap;
        for &byte in data {
            self.buf[tail] = byte;
            tail = (tail + 1) % cap;
        }
        self.len += data.len();
        Ok(())
    }

    /// Copies bytes into `out` without removing them. Returns the count.
    pub fn peek(&self, out: &mut [u8]) -> usize {
        let n = out.len().min(self.len);
        let cap = self.capacity();
        for i in 0..n {
            out[i] = self.buf[(self.head + i) % cap];
        }
        n
    }

    /// Copies bytes into `out` and removes them. Returns the count.
    pub fn read(&mut self, out: &mut [u8]) -> usize {
        let n = self.peek(out);
        self.head = (self.head + n) % self.capacity();
        self.len -= n;
        n
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn wraps_around() {
        let mut rb = RingBuffer::with_capacity(4);
        rb.write(b"abc").unwrap();
        let mut two = [0u8; 2];
        assert_eq!(rb.read(&mut two), 2);
        rb.write(b"de").unwrap(); // wraps past the end of the vec
        let mut rest = [0u8; 4];
        let n = rb.read(&mut rest);
        assert_eq!(&rest[..n], b"cde");
    }

    #[test]
    fn rejects_overflow() {
        let mut rb = RingBuffer::with_capacity(3);
        assert_eq!(rb.write(b"abcd"), Err(Full { free: 3 }));
        assert!(rb.is_empty());
    }
}

# kvstore-lite

A tiny embedded key-value store written in Rust. Single file, no dependencies besides `std`.

## Usage

```rust
use kvstore_lite::Store;

fn main() -> std::io::Result<()> {
    let mut store = Store::open("data.kv")?;
    store.put(b"alpha", b"1")?;
    store.put(b"beta", b"2")?;

    assert_eq!(store.get(b"alpha")?, Some(b"1".to_vec()));
    store.delete(b"beta")?;
    store.compact()?;
    Ok(())
}
```

## Design notes

- Append-only log with an in-memory hash index.
- `compact()` rewrites live entries into a fresh file and swaps it in with an atomic rename.
- Every record carries a CRC32; a bad checksum at the tail is treated as a torn write and truncated.

## Limitations

- The whole key set must fit in memory.
- Only one process may open a file at a time (advisory lock).
- No range scans.

