from dataclasses import dataclass, field
from typing import Iterator


@dataclass
class Matrix:
    rows: int
    cols: int
    data: list[float] = field(default_factory=list)

    def __post_init__(self):
        if not self.data:
            self.data = [0.0] * (self.rows * self.cols)
        if len(self.data) != self.rows * self.cols:
            raise ValueError("data length does not match shape")

    def __getitem__(self, pos: tuple[int, int]) -> float:
        r, c = pos
        return self.data[r * self.cols + c]

    def __setitem__(self, pos: tuple[int, int], value: float) -> None:
        r, c = pos
        self.data[r * self.cols + c] = value

    def transpose(self) -> "Matrix":
        out = Matrix(self.cols, self.rows)
        for r in range(self.rows):
            for c in range(self.cols):
                out[c, r] = self[r, c]
        return out

    def __iter__(self) -> Iterator[float]:
        return iter(self.data)

