/* debounce.ts */
export type AnyFn = (...args: any[]) => void;

export interface DebounceOptions {
  /** Fire on the leading edge instead of the trailing one. */
  leading?: boolean;
  /** Longest time the call may be postponed, in milliseconds. */
  maxWait?: number;
}

export function debounce<F extends AnyFn>(fn: F, wait: number, opts: DebounceOptions = {}) {
  let timer: ReturnType<typeof setTimeout> | undefined;
  let firstCall = 0;
  let lastArgs: Parameters<F> | undefined;

  const flush = () => {
    if (lastArgs) {
      fn(...lastArgs);
      lastArgs = undefined;
    }
    timer = undefined;
    firstCall = 0;
  };

  return (...args: Parameters<F>) => {
    const now = Date.now();
    if (!firstCall) firstCall = now;
    if (opts.leading && !timer) fn(...args);
    else lastArgs = args;

    if (timer) clearTimeout(timer);
    const remaining = opts.maxWait ? Math.max(0, opts.maxWait - (now - firstCall)) : wait;
    timer = setTimeout(flush, Math.min(wait, remaining));
  };
}

// debounce.js - small utility used by the search box
'use strict';

/**
 * Returns a function that delays calling fn until `wait` ms have passed
 * since the last time it was invoked.
 */
function debounce(fn, wait = 200, { leading = false } = {}) {
  let timer = null;
  return function debounced(...args) {
    const callNow = leading && timer === null;
    clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      if (!leading) fn.apply(this, args);
    }, wait);
    if (callNow) fn.apply(this, args);
  };
}

