    let mut map = HashMap::new();
    for c in s.chars() {
        *map.entry(c).or_insert(0) += 1;
    }
    map
}

/// Returns true when both strings are anagrams, ignoring case and spaces.
pub fn is_anagram(a: &str, b: &str) -> bool {
    let clean = |t: &str| t.to_lowercase().replace(' ', "");
    char_frequencies(&clean(a)) == char_frequencies(&clean(b))
}

