// ring_buffer.go - fixed-size ring buffer used by the metrics sampler
package sampler

import "sync"

// Ring holds the most recent N float64 samples.
type Ring struct {
	mu   sync.Mutex
	data []float64
	head int
	full bool
}

func NewRing(n int) *Ring {
	if n <= 0 {
		panic("ring size must be positive")
	}
	return &Ring{data: make([]float64, n)}
}

// Push overwrites the oldest sample once the buffer is full.
func (r *Ring) Push(v float64) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.data[r.head] = v
	r.head = (r.head + 1) % len(r.data)
	if r.head == 0 {
		r.full = true
	}
}

// Snapshot returns samples ordered from oldest to newest.
func (r *Ring) Snapshot() []float64 {
	r.mu.Lock()
	defer r.mu.Unlock()
	if !r.full {
		return append([]float64(nil), r.data[:r.head]...)
	}
	out := make([]float64, 0, len(r.data))
	out = append(out, r.data[r.head:]...)
	return append(out, r.data[:r.head]...)
}

