// retry.go - exponential backoff helper
package retry

import (
	"context"
	"errors"
	"math/rand"
	"time"
)

// ErrExhausted is returned when every attempt failed.
var ErrExhausted = errors.New("retry: attempts exhausted")

// Do calls fn up to attempts times. The delay doubles after each failure,
// starting at base, and never exceeds ceiling. A little jitter keeps many
// callers from retrying in lockstep.
func Do(ctx context.Context, attempts int, base, ceiling time.Duration, fn func() error) error {
	delay := base
	for i := 0; i < attempts; i++ {
		if err := fn(); err == nil {
			return nil
		}
		jitter := time.Duration(rand.Int63n(int64(delay) / 4))
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-time.After(delay + jitter):
		}
		delay *= 2
		if delay > ceiling {
			delay = ceiling
		}
	}
	return ErrExhausted
}

