// ringbuffer.go
package ring

import "errors"

var ErrEmpty = errors.New("ring: buffer is empty")

// Buffer is a fixed-capacity FIFO queue of ints.
// The zero value is not usable; call New.
type Buffer struct {
	data  []int
	head  int
	count int
}

// New returns a Buffer that holds at most n items.
func New(n int) *Buffer {
	if n <= 0 {
		panic("ring: capacity must be positive")
	}
	return &Buffer{data: make([]int, n)}
}

// Push appends v. When the buffer is full the oldest item is overwritten.
func (b *Buffer) Push(v int) {
	tail := (b.head + b.count) % len(b.data)
	b.data[tail] = v
	if b.count == len(b.data) {
		b.head = (b.head + 1) % len(b.data)
	} else {
		b.count++
	}
}

// Pop removes and returns the oldest item.
func (b *Buffer) Pop() (int, error) {
	if b.count == 0 {
		return 0, ErrEmpty
	}
	v := b.data[b.head]
	b.head = (b.head + 1) % len(b.data)
	b.count--
	return v, nil
}

// Len reports how many items are stored.
func (b *Buffer) Len() int { return b.count }

