package com.example.util;

import java.util.ArrayDeque;
import java.util.Deque;

/**
 * Evaluates simple postfix (reverse Polish) expressions such as "3 4 + 2 *".
 */
public final class Rpn {
    private Rpn() {}

    public static long eval(String expr) {
        Deque<Long> stack = new ArrayDeque<>();
        for (String tok : expr.trim().split("\\s+")) {
            switch (tok) {
                case "+" -> stack.push(stack.pop() + stack.pop());
                case "*" -> stack.push(stack.pop() * stack.pop());
                case "-" -> {
                    long b = stack.pop();
                    long a = stack.pop();
                    stack.push(a - b);
                }
                case "/" -> {
                    long b = stack.pop();
                    long a = stack.pop();
                    if (b == 0) throw new ArithmeticException("division by zero");
                    stack.push(a / b);
                }
                default -> stack.push(Long.parseLong(tok));
            }
        }
        if (stack.size() != 1) throw new IllegalArgumentException("malformed expression");
        return stack.pop();
    }
}

