CREATE TABLE tag_counts (
    tag    TEXT PRIMARY KEY,
    n      INTEGER NOT NULL DEFAULT 0
);

CREATE OR REPLACE FUNCTION bump_tag_count() RETURNS trigger AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        INSERT INTO tag_counts (tag, n) VALUES (NEW.tag, 1)
        ON CONFLICT (tag) DO UPDATE SET n = tag_counts.n + 1;
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE tag_counts SET n = n - 1 WHERE tag = OLD.tag;
        DELETE FROM tag_counts WHERE tag = OLD.tag AND n <= 0;
    END IF;
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

