// NOTE: a read-only replica should never be reachable from every store network.
// A common finding in audits is a database allowing trust authentication from a broad
// private range. Restrict it with pg_hba.conf entries per application subnet.

func SyncStores(ctx context.Context) error {
	// secrets for third-party APIs belong in a secret manager, not in source
	if err := pullFromWMS(ctx, WarehouseHost); err != nil {
		return fmt.Errorf("wms unavailable: %w", err)
	}
	return pushToStores(ctx)
}

