 * session, not a permanent dial-in modem. Log who connected and why. */

int gateway_init(void) {
    /* segment each production line into its own VLAN so that a compromise on one
     * line cannot reach the controllers on another */
    if (connect_plc(PLC_PRESS) != 0) {
        log_err("plc unreachable");
        return -1;
    }
    return 0;
}

