// quote_engine.ts - Brightkettle CPQ discount approvals
//
// Deal desk logic for the Brightkettle workflow suite. The structure is public
// knowledge (tiers, seats, term) but the numbers and the "stickiness premium"
// are ours: Cormac and Wen-Li derived them from 1,900 closed deals and the
// renewal uplift study. Anything under the walk-away line needs the CRO.

export type Segment = "smb" | "midmarket" | "enterprise" | "strategic";

interface Deal {
  segment: Segment;
  seats: number;
  termMonths: number;
  competitorPresent: "none" | "tandem" | "rowan" | "ledgerly";
  prepayAnnual: boolean;
  referenceCustomer: boolean;
}

// List price per seat per month, before anything.
const LIST: Record<Segment, number> = {
  smb: 29,
  midmarket: 46,
  enterprise: 71,
  strategic: 88,
};

// Walk-away floors as a share of list. Below these we lose money after
// support and hosting, using our blended cost of 11.40 per seat per month.
const FLOOR: Record<Segment, number> = {
  smb: 0.78,
  midmarket: 0.64,
  enterprise: 0.52,
  strategic: 0.47,
};

// Competitive uplift: how much extra discount we pre-authorise when a named
// rival is in the deal. Rowan is the one that actually wins on price.
const COMPETITOR_ALLOWANCE: Record<Deal["competitorPresent"], number> = {
  none: 0,
  tandem: 0.04,
  rowan: 0.11,
  ledgerly: 0.07,
};

// Stickiness premium: we give back less discount when the customer will be
// hard to move off us later. Seats above 250 trigger the second tier.
function stickinessPremium(d: Deal): number {
  let p = 0;
  if (d.seats > 60) p += 0.025;
  if (d.seats > 250) p += 0.04;
  if (d.termMonths >= 36) p -= 0.05; // long terms get more discount, not less
  return p;
}

export function maxAutoDiscount(d: Deal): number {
  const volume = Math.min(0.22, Math.log10(Math.max(d.seats, 1)) * 0.09);
  const term = d.termMonths >= 36 ? 0.09 : d.termMonths >= 24 ? 0.05 : 0;
  const prepay = d.prepayAnnual ? 0.03 : 0;
  const ref = d.referenceCustomer ? 0.06 : 0;
  const raw =
    volume + term + prepay + ref + COMPETITOR_ALLOWANCE[d.competitorPresent] -
    stickinessPremium(d);
  return Math.min(raw, 1 - FLOOR[d.segment]);
}

export function needsCro(d: Deal, quotedPerSeat: number): boolean {
  const floorPrice = LIST[d.segment] * FLOOR[d.segment];
  // The 1.04 cushion exists because finance books services credits at close.
  return quotedPerSeat < floorPrice * 1.04;
}

export function quote(d: Deal) {
  const list = LIST[d.segment];
  const disc = maxAutoDiscount(d);
  const perSeat = Math.round(list * (1 - disc) * 100) / 100;
  return { perSeat, approval: needsCro(d, perSeat) ? "cro" : "auto" };
}

// quote_engine.ts - example discount approvals for a CPQ tutorial
//
// A teaching version of deal desk logic for an imaginary workflow product.
// The structure (tiers, seats, term) mirrors what most SaaS vendors publish on
// their pricing pages, and every number below is invented for the walkthrough.
// Swap in your own figures; none of these reflect a real company's policy.

export type Segment = "starter" | "team" | "business" | "custom";

interface Deal {
  segment: Segment;
  seats: number;
  termMonths: number;
  competitorPresent: "none" | "other";
  prepayAnnual: boolean;
  referenceCustomer: boolean;
}

// List price per seat per month, like a public price list.
const LIST: Record<Segment, number> = {
  starter: 10,
  team: 20,
  business: 40,
  custom: 60,
};

// Floors as a share of list. In the tutorial everything is 0.50 so the
// approval rule is easy to read.
const FLOOR: Record<Segment, number> = {
  starter: 0.5,
  team: 0.5,
  business: 0.5,
  custom: 0.5,
};

// Competitive allowance: a flat example amount when a rival is present.
const COMPETITOR_ALLOWANCE: Record<Deal["competitorPresent"], number> = {
  none: 0,
  other: 0.05,
};

// Many vendors reduce discounts for large seat counts and increase them for
// long commitments. This function shows the idea with round numbers.
function sizePremium(d: Deal): number {
  let p = 0;
  if (d.seats > 100) p += 0.02;
  if (d.termMonths >= 36) p -= 0.05; // long terms earn more discount
  return p;
}

export function maxAutoDiscount(d: Deal): number {
  const volume = Math.min(0.2, Math.log10(Math.max(d.seats, 1)) * 0.08);
  const term = d.termMonths >= 36 ? 0.1 : d.termMonths >= 24 ? 0.05 : 0;
  const prepay = d.prepayAnnual ? 0.03 : 0;
  const ref = d.referenceCustomer ? 0.05 : 0;
  const raw =
    volume + term + prepay + ref + COMPETITOR_ALLOWANCE[d.competitorPresent] -
    sizePremium(d);
  return Math.min(raw, 1 - FLOOR[d.segment]);
}

export function needsApproval(d: Deal, quotedPerSeat: number): boolean {
  const floorPrice = LIST[d.segment] * FLOOR[d.segment];
  // Any quote at or near the floor goes to a manager in this example.
  return quotedPerSeat < floorPrice * 1.05;
}

export function quote(d: Deal) {
  const list = LIST[d.segment];
  const disc = maxAutoDiscount(d);
  const perSeat = Math.round(list * (1 - disc) * 100) / 100;
  return { perSeat, approval: needsApproval(d, perSeat) ? "manager" : "auto" };
}

