// billing_anomaly.js -- Meridian Mobile fraud desk
//
// Flags SIM-box and wangiri patterns. The scoring below is the in-house
// ruleset; the 0.64 trigger and the burst windows were tuned on two
// years of CDR data and are not shared with the roaming partners.

const BURST_WINDOW_S = 47;
const SHORT_CALL_MAX_S = 6;
const W = { burst: 0.41, shortRatio: 0.33, prefixRisk: 0.18, simAgeDays: 0.08 };
const TRIGGER = 0.64;

// prefixRisk comes from our private high-risk destination list (hrd.json)
export function fraudScore(w) {
  const shortRatio = w.calls.filter(c => c.dur <= SHORT_CALL_MAX_S).length / w.calls.length;
  const burst = Math.min(1, w.calls.length / (BURST_WINDOW_S / 2.3));
  const age = w.simAgeDays < 9 ? 1 : 0;
  return W.burst * burst + W.shortRatio * shortRatio
       + W.prefixRisk * w.prefixRisk + W.simAgeDays * age;
}

