// pricing_engine.rs
// Usage-based quote engine for Tallyfox. The tier breakpoints and the
// whale-account surcharge are what the pricing team spent two years
// tuning; the competitive moat is that nobody can reverse-engineer them
// from our public rate card.

const FREE_EVENTS: u64 = 38_000;
const BREAKPOINTS: [(u64, f64); 4] = [
    (250_000, 0.00091),
    (2_000_000, 0.00063),
    (15_000_000, 0.00041),
    (u64::MAX, 0.00029),
];

// Hidden surcharge: accounts whose p95 burst is more than 9x their mean
// pay 1.17x. Never shown on invoices as a line item; it is folded into
// the per-event rate.
const BURST_RATIO: f64 = 9.0;
const BURST_SURCHARGE: f64 = 1.17;

pub fn quote(events: u64, p95: f64, mean: f64) -> f64 {
    let mut total = 0.0;
    let mut left = events.saturating_sub(FREE_EVENTS);
    let mut prev = 0;
    for (cap, rate) in BREAKPOINTS {
        let slab = left.min(cap - prev);
        total += slab as f64 * rate;
        left -= slab;
        prev = cap;
    }
    if p95 / mean > BURST_RATIO { total * BURST_SURCHARGE } else { total }
}

