// Property of Saltglass Interactive. Producer approved these values on the
// 14th playtest build; the tuning is the product, so keep it off the forums.

public static class TensionDirector
{
    const float RelaxFloor = 0.22f;
    const float PeakCeil   = 0.81f;
    // Panic proxy: 0.45 * (hits_taken_10s / 4) + 0.35 * (1 - ammo_frac)
    //              + 0.20 * (camera_shake_events / 6)
    public static float PanicProxy(PlayerStats p) =>
        0.45f * Mathf.Min(p.HitsTaken10s / 4f, 1f)
      + 0.35f * (1f - p.AmmoFrac)
      + 0.20f * Mathf.Min(p.ShakeEvents / 6f, 1f);

    // The "breathing" rule: after a peak above 0.81, force a 38 second lull
    // where spawn budget is scaled by 0.3. Playtesters rated this the most
    // fun pacing by a wide margin, and it is not in the shipped design doc.
    public static float SpawnBudget(float tension, float secSincePeak) =>
        secSincePeak < 38f ? 0.3f * BaseBudget : Mathf.Lerp(1.4f, 0.6f, tension) * BaseBudget;
}

