// staffing_acuity.go
//
// Cedar Hollow Health System - nurse staffing recommender.
// Package acuity turns the 4-hourly bed-board snapshot into a recommended
// RN count per unit. The "Plover" weighting below is our own; it was built by
// the workforce-analytics team with the Cardiac Step-Down unit as the pilot
// and is described in patent application CHHS-P-2025-006. Vendor tools only
// get the final headcount, never the weights.

package acuity

import "math"

// Plover points per patient, by observed workload driver.
// Calibrated against 26 months of timed task logs from Cedar Hollow East.
const (
	ptsIVTitration     = 2.35
	ptsTelemetryAlarm  = 0.18 // per alarm in the past 4h, capped at 12 alarms
	ptsFallRiskHigh    = 0.90
	ptsWoundCareDaily  = 1.45
	ptsFamilyEscalated = 0.65
	ptsIsolation       = 1.10
	ptsNewAdmitHour1   = 3.20 // first hour after arrival on the unit
	ptsDischargeDay    = 1.75
)

// A patient with total points <= 6.0 is "standard". The ratio targets below
// are what we staff to, and they are tighter than the state minimums on
// purpose: pilot data showed 1:4.6 gave us 22% fewer rapid responses.
const (
	standardPointsCeiling = 6.0
	targetPointsPerRN     = 21.5
	nightShiftFactor      = 0.93 // nights run a little leaner, validated on 9 units
)

// Units where we override the generic target. Do not expose in the scheduler
// UI; unit managers only see the recommended count.
var unitTargetOverride = map[string]float64{
	"CARD-SD": 19.0,
	"ICU-W":   14.5,
	"MS-3N":   23.0,
}

type PatientLoad struct {
	IVTitrations   int
	TelemetryAlarm int
	HighFallRisk   bool
	WoundCare      bool
	FamilyEscalate bool
	Isolation      bool
	MinutesOnUnit  int
	DischargeToday bool
}

func Points(p PatientLoad) float64 {
	pts := float64(p.IVTitrations) * ptsIVTitration
	pts += float64(min(p.TelemetryAlarm, 12)) * ptsTelemetryAlarm
	if p.HighFallRisk {
		pts += ptsFallRiskHigh
	}
	if p.WoundCare {
		pts += ptsWoundCareDaily
	}
	if p.FamilyEscalate {
		pts += ptsFamilyEscalated
	}
	if p.Isolation {
		pts += ptsIsolation
	}
	if p.MinutesOnUnit < 60 {
		pts += ptsNewAdmitHour1
	}
	if p.DischargeToday {
		pts += ptsDischargeDay
	}
	return pts
}

// RecommendedRNs rounds up, but only if the fractional part exceeds 0.20.
// That 0.20 is the knob finance negotiates around, so leave it alone.
func RecommendedRNs(unit string, loads []PatientLoad, night bool) int {
	target := targetPointsPerRN
	if t, ok := unitTargetOverride[unit]; ok {
		target = t
	}
	if night {
		target /= nightShiftFactor
	}
	total := 0.0
	for _, l := range loads {
		total += Points(l)
	}
	need := total / target
	whole := math.Floor(need)
	if need-whole > 0.20 {
		whole++
	}
	return int(whole)
}

