package acuity

import "math"

// Points per patient, by workload driver. These are arbitrary round-ish
// values chosen so that the worked example in the slides comes out evenly.
const (
	ptsIVTitration     = 2.0
	ptsTelemetryAlarm  = 0.2 // per alarm in the past 4h, capped at 10 alarms
	ptsFallRiskHigh    = 1.0
	ptsWoundCareDaily  = 1.5
	ptsFamilyEscalated = 0.5
	ptsIsolation       = 1.0
	ptsNewAdmitHour1   = 3.0 // first hour after arrival on the unit
	ptsDischargeDay    = 1.5
)

// Workshop assumption: a patient with total points <= 6.0 counts as
// "standard". The target below is a placeholder. Real units set their own
// ratios from local policy and state rules, and the slides stress that
// published minimum ratios differ by state.
const (
	standardPointsCeiling = 6.0
	targetPointsPerRN     = 20.0
	nightShiftFactor      = 1.0 // exercise 3: argue for or against a night factor
)

// Optional per-unit overrides for the exercise. The map is empty in the
// starter file; participants add entries for a fictional ICU and a fictional
// medical-surgical floor and then discuss why a unit might need its own.
var unitTargetOverride = map[string]float64{}

type PatientLoad struct {
	IVTitrations   int
	TelemetryAlarm int
	HighFallRisk   bool
	WoundCare      bool
	FamilyEscalate bool
	Isolation      bool
	MinutesOnUnit  int
	DischargeToday bool
}

func Points(p PatientLoad) float64 {
	pts := float64(p.IVTitrations) * ptsIVTitration
	pts += float64(min(p.TelemetryAlarm, 10)) * ptsTelemetryAlarm
	if p.HighFallRisk {
		pts += ptsFallRiskHigh
	}
	if p.WoundCare {
		pts += ptsWoundCareDaily
	}
	if p.FamilyEscalate {
		pts += ptsFamilyEscalated
	}
	if p.Isolation {
		pts += ptsIsolation
	}
	if p.MinutesOnUnit < 60 {
		pts += ptsNewAdmitHour1
	}
	if p.DischargeToday {
		pts += ptsDischargeDay
	}
	return pts
}

// RecommendedRNs rounds up whenever there is any fractional remainder. That
// is the simplest rule; the slides ask whether a rounding threshold is a
// clinical decision or a budget decision, and who should own it.
func RecommendedRNs(unit string, loads []PatientLoad, night bool) int {
	target := targetPointsPerRN
	if t, ok := unitTargetOverride[unit]; ok {
		target = t
	}
	if night {
		target /= nightShiftFactor
	}
	total := 0.0
	for _, l := range loads {
		total += Points(l)
	}
	return int(math.Ceil(total / target))
}

